import os, sys
sys.path.insert(0, os.getcwd())
import sqlite3
from src.repository import initialize, balance
from src.service import transfer
from src.events import Recorder


def fresh():
    c = sqlite3.connect(":memory:")
    initialize(c)
    c.executemany("INSERT INTO accounts VALUES (?, ?)", [("a", 100), ("b", 20)])
    c.commit()
    return c


def state(c):
    return (balance(c, "a"), balance(c, "b"),
            c.execute("SELECT COUNT(*) FROM ledger").fetchone()[0])


# Invalid transfers raise ValueError with no writes and no publication.
for args in [("a", "a", 10), ("a", "zz", 10), ("zz", "b", 10),
             ("a", "b", 0), ("a", "b", -5), ("a", "b", True),
             ("a", "b", 1.0), ("a", "b", 101)]:
    c, p = fresh(), Recorder()
    before = state(c)
    try:
        transfer(c, p, *args)
    except ValueError:
        pass
    else:
        raise AssertionError(f"expected ValueError for {args}")
    assert state(c) == before, args
    assert p.events == [], args
    assert not c.in_transaction, args

# Successful transfer: exact effects, one ledger row, one publication.
c, p = fresh(), Recorder()
transfer(c, p, "a", "b", 100)
assert state(c) == (0, 120, 1)
assert p.events == [{"source": "a", "target": "b", "amount": 100}]
assert not c.in_transaction


class FailingConnection:
    """Proxy that raises on the n-th execute call or on commit."""
    def __init__(self, conn, fail_at_execute=None, fail_commit=False):
        self._c = conn
        self._n = 0
        self._fail_at = fail_at_execute
        self._fail_commit = fail_commit

    def execute(self, sql, *params):
        self._n += 1
        if self._fail_at is not None and self._n == self._fail_at:
            raise sqlite3.OperationalError("injected failure")
        return self._c.execute(sql, *params)

    def commit(self):
        if self._fail_commit:
            raise sqlite3.OperationalError("injected commit failure")
        return self._c.commit()

    def rollback(self):
        return self._c.rollback()


# Failure at any statement or at commit rolls everything back and never publishes.
for n in range(1, 7):  # BEGIN, 2 balance reads, 2 UPDATEs, 1 INSERT
    c, p = fresh(), Recorder()
    before = state(c)
    try:
        transfer(FailingConnection(c, fail_at_execute=n), p, "a", "b", 10)
    except sqlite3.OperationalError:
        assert state(c) == before, n
        assert p.events == [], n
        assert not c.in_transaction, n
    else:
        raise AssertionError(f"no failure injected at statement {n}")

c, p = fresh(), Recorder()
before = state(c)
try:
    transfer(FailingConnection(c, fail_commit=True), p, "a", "b", 10)
except sqlite3.OperationalError:
    pass
else:
    raise AssertionError("commit failure not raised")
assert state(c) == before and p.events == []


# Publication failure propagates after the committed transfer and is not undone.
class BrokenPublisher:
    def publish(self, event):
        raise RuntimeError("bus down")

c = fresh()
try:
    transfer(c, BrokenPublisher(), "a", "b", 10)
except RuntimeError:
    pass
else:
    raise AssertionError("publish failure not propagated")
assert state(c) == (90, 30, 1)

print("transfer contract checks passed")

